import { useState, useEffect, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import toast from 'react-hot-toast'
import { ArrowLeft, Package, Wrench, Bike } from 'lucide-react'
import type { CustomerOrderStatus } from '../types.js'
import { ORDER_STATUS_LABELS, ORDER_STATUS_COLORS, LINE_TYPE_LABELS } from '../types.js'
import { getOrder, updateOrderStatus, type OrderDetailApiResponse } from '../api.js'
import { formatCentsToEuro } from '@/shared/lib/utils'
import { CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface OrderDetailPanelProps {
  orderId: string
}

/** Status transitions allowed from each state */
const STATUS_TRANSITIONS: Record<CustomerOrderStatus, Array<{ to: CustomerOrderStatus; label: string }>> = {
  pending: [
    { to: 'ordered', label: 'Mark Ordered' },
    { to: 'cancelled', label: 'Cancel Order' },
  ],
  ordered: [
    { to: 'ready', label: 'Mark Ready for Pickup' },
    { to: 'cancelled', label: 'Cancel Order' },
  ],
  ready: [
    { to: 'fulfilled', label: 'Mark Fulfilled' },
    { to: 'cancelled', label: 'Cancel Order' },
  ],
  fulfilled: [], // terminal state
  cancelled: [], // terminal state
}

// ---------------------------------------------------------------------------
// Component — Status Badge
// ---------------------------------------------------------------------------

function StatusBadge({ status }: { status: CustomerOrderStatus }) {
  return (
    <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${ORDER_STATUS_COLORS[status]}`}>
      {ORDER_STATUS_LABELS[status]}
    </span>
  )
}

// ---------------------------------------------------------------------------
// Component — Line Type Icon
// ---------------------------------------------------------------------------

function LineTypeIcon({ lineType }: { lineType: string }) {
  switch (lineType) {
    case 'part': return <Package className="h-4 w-4 text-muted-foreground" />
    case 'labor': return <Wrench className="h-4 w-4 text-muted-foreground" />
    case 'bicycle': return <Bike className="h-4 w-4 text-muted-foreground" />
    default: return null
  }
}

// ---------------------------------------------------------------------------
// Component — Date Formatter
// ---------------------------------------------------------------------------

function formatDate(epochMs: number | null): string {
  if (!epochMs) return '—'
  return new Date(epochMs).toLocaleDateString('en-IE', {
    year: 'numeric',
    month: 'short',
    day: '2-digit',
  })
}

// ---------------------------------------------------------------------------
// Component — Order Detail Panel
// ---------------------------------------------------------------------------

export function OrderDetailPanel({ orderId }: OrderDetailPanelProps) {
  const navigate = useNavigate()
  const [detail, setDetail] = useState<OrderDetailApiResponse | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [transitioning, setTransitioning] = useState(false)

  // Fetch order detail
  const fetchOrder = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const data = await getOrder(orderId)
      setDetail(data)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load order')
    } finally {
      setLoading(false)
    }
  }, [orderId])

  useEffect(() => {
    fetchOrder()
  }, [fetchOrder])

  // Handle status transition
  const handleTransition = async (newStatus: CustomerOrderStatus) => {
    setTransitioning(true)
    try {
      await updateOrderStatus(orderId, newStatus)
      toast.success(`Order marked as ${ORDER_STATUS_LABELS[newStatus].toLowerCase()}`)
      await fetchOrder()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to update status')
    } finally {
      setTransitioning(false)
    }
  }

  // Back to list
  const handleBack = () => navigate('/orders')

  if (loading) {
    return (
      <div className="flex flex-col h-full">
        <CardHeader className="pb-2 px-6 pt-4">
          <CardTitle className="text-xl">Loading order…</CardTitle>
        </CardHeader>
      </div>
    )
  }

  if (error || !detail) {
    return (
      <div className="flex flex-col h-full">
        <CardHeader className="pb-2 px-6 pt-4">
          <div className="flex items-center gap-3">
            <Button variant="ghost" size="sm" onClick={handleBack}>
              <ArrowLeft className="h-4 w-4 mr-1" /> Back
            </Button>
          </div>
        </CardHeader>
        <CardContent className="px-6 pb-6">
          <div className="p-3 bg-red-50 border border-red-200 rounded text-sm text-red-700 dark:bg-red-900/20 dark:border-red-800 dark:text-red-400">
            {error || 'Order not found'}
          </div>
        </CardContent>
      </div>
    )
  }

  const { order, lineItems, depositPaid } = detail
  const availableTransitions = STATUS_TRANSITIONS[order.status] ?? []

  // Compute totals from line items
  const totalNet = lineItems.reduce((sum, item) => sum + item.lineTotalNet, 0)
  const totalVat = lineItems.reduce((sum, item) => sum + item.lineTotalVat, 0)
  const totalGross = lineItems.reduce((sum, item) => sum + item.lineTotalGross, 0)

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <CardHeader className="pb-2 px-6 pt-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Button variant="ghost" size="sm" onClick={handleBack}>
              <ArrowLeft className="h-4 w-4 mr-1" /> Back
            </Button>
            <CardTitle className="text-xl">{order.orderNumber}</CardTitle>
            <StatusBadge status={order.status} />
          </div>

          {/* Status transition buttons */}
          {availableTransitions.length > 0 && (
            <div className="flex gap-2">
              {availableTransitions.map((transition) => (
                <Button
                  key={transition.to}
                  variant={transition.to === 'cancelled' ? 'outline' : 'default'}
                  size="sm"
                  onClick={() => handleTransition(transition.to)}
                  disabled={transitioning}
                  className={transition.to === 'cancelled' ? 'text-red-600 hover:text-red-700 border-red-200' : ''}
                >
                  {transition.label}
                </Button>
              ))}
            </div>
          )}
        </div>
      </CardHeader>

      {/* Content */}
      <CardContent className="px-6 pb-6 flex-1 overflow-auto space-y-6">
        {/* Order Info Grid */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
          <div>
            <span className="text-muted-foreground block text-xs">Customer</span>
            <span className="font-medium">{order.customerId ? `ID: ${order.customerId.slice(0, 8)}…` : 'Unknown'}</span>
          </div>
          <div>
            <span className="text-muted-foreground block text-xs">Created</span>
            <span>{formatDate(order.createdAt)}</span>
          </div>
          <div>
            <span className="text-muted-foreground block text-xs">Expected Delivery</span>
            <span>{formatDate(order.expectedDeliveryDate)}</span>
          </div>
          <div>
            <span className="text-muted-foreground block text-xs">Deposit Paid</span>
            <span className="font-mono">{formatCentsToEuro(depositPaid)}</span>
          </div>
        </div>

        {/* Internal Notes */}
        {order.internalNotes && (
          <div className="p-3 bg-muted/50 rounded-md text-sm">
            <span className="text-muted-foreground block text-xs mb-1">Internal Notes</span>
            <span>{order.internalNotes}</span>
          </div>
        )}

        {/* Line Items Table */}
        <div>
          <h3 className="text-sm font-medium text-muted-foreground mb-2">Line Items ({lineItems.length})</h3>
          <div className="border rounded-lg overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-muted/50 border-b">
                  <th className="text-left px-4 py-2 font-medium text-muted-foreground w-16">Type</th>
                  <th className="text-left px-4 py-2 font-medium text-muted-foreground">Description</th>
                  <th className="text-center px-4 py-2 font-medium text-muted-foreground w-16">Qty</th>
                  <th className="text-right px-4 py-2 font-medium text-muted-foreground w-28">Unit Price</th>
                  <th className="text-right px-4 py-2 font-medium text-muted-foreground w-28">Total (net)</th>
                </tr>
              </thead>
              <tbody>
                {lineItems.map((item) => (
                  <tr key={item.id} className="border-b last:border-b-0 hover:bg-muted/30 transition-colors">
                    <td className="px-4 py-2">
                      <div className="flex items-center gap-1.5">
                        <LineTypeIcon lineType={item.lineType} />
                        <span className="text-xs text-muted-foreground">{LINE_TYPE_LABELS[item.lineType as keyof typeof LINE_TYPE_LABELS] ?? item.lineType}</span>
                      </div>
                    </td>
                    <td className="px-4 py-2">{item.description}</td>
                    <td className="px-4 py-2 text-center tabular-nums">{item.quantity}</td>
                    <td className="px-4 py-2 text-right font-mono tabular-nums">{formatCentsToEuro(item.unitPriceNet)}</td>
                    <td className="px-4 py-2 text-right font-mono tabular-nums">{formatCentsToEuro(item.lineTotalNet)}</td>
                  </tr>
                ))}
              </tbody>
              <tfoot>
                <tr className="bg-muted/30">
                  <td colSpan={4} className="px-4 py-2 text-right font-medium">Totals:</td>
                  <td className="px-4 py-2 text-right font-mono tabular-nums">
                    <div className="text-xs space-y-0.5">
                      <div className="flex justify-between gap-8">
                        <span className="text-muted-foreground">Net:</span>
                        <span>{formatCentsToEuro(totalNet)}</span>
                      </div>
                      <div className="flex justify-between gap-8 text-xs text-muted-foreground">
                        <span>VAT:</span>
                        <span>{formatCentsToEuro(totalVat)}</span>
                      </div>
                      <div className="flex justify-between gap-8 font-medium border-t pt-1 mt-1">
                        <span>Gross:</span>
                        <span>{formatCentsToEuro(totalGross)}</span>
                      </div>
                    </div>
                  </td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>

        {/* Deposit Summary */}
        {depositPaid > 0 && (
          <div className="p-4 bg-accent rounded-md text-sm">
            <h3 className="font-medium mb-2">Deposit Summary</h3>
            <div className="grid grid-cols-3 gap-4">
              <div>
                <span className="text-muted-foreground block text-xs">Total (net)</span>
                <span className="font-mono">{formatCentsToEuro(totalNet)}</span>
              </div>
              <div>
                <span className="text-muted-foreground block text-xs">Deposit Paid</span>
                <span className="font-mono text-green-600 dark:text-green-400">{formatCentsToEuro(depositPaid)}</span>
              </div>
              <div>
                <span className="text-muted-foreground block text-xs">Balance Due</span>
                <span className="font-mono">{formatCentsToEuro(Math.max(0, totalNet - depositPaid))}</span>
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </div>
  )
}

